6. **主角设定必须贴合题材**：主角的身份、能力、背景必须严格符合用户选择的题材特征。例如仙侠题材→主角应为修士/凡人修仙；都市题材→主角应为现代人；历史题材→主角应为历史人物或穿越者。
7. **核矛盾必须围绕关键词**：核心冲突必须直接围绕用户关键词展开，禁止生成与关键词无关的冲突。

