// ============================================================
// 导出所有提示词
// ============================================================
// ============================================================
// 题材检测与专属规则动态注入
// ============================================================

const HONGHUANG_KEYWORDS = /洪荒|封神|阐教|截教|巫族|祖巫|三清|女娲|伏羲|神农|黄帝|蚩尤|商周|封神榜|天庭|妖庭|鲲鹏|太一|帝俊|盘古|开天|龙凤麒麟|量劫|斩三尸|圣人|混元大罗金仙|先天灵宝|巫道|巫术|图腾/
const WESTERN_KEYWORDS = /西幻|魔法|斗气|骑士|教廷|法师|牧师|精灵|矮人|巨龙|魔兽|位面|魔核|圣光|炼金|魔导|圣剑|圣骑士|魔法学院|盘龙|龙血战士/
const SCIFI_KEYWORDS = /科幻|星际|机甲|基因|未来|太空|飞船|光年|外星人|AI|人工智能|末世|异能|进化/
const XIANXIA_KEYWORDS = /修仙|修真|仙侠|玄幻|宗门|金丹|元婴|化神|渡劫|练气|筑基|灵根|灵气/
const HISTORY_KEYWORDS = /历史|权谋|种田|经商|朝代|皇帝|将军|官场|科举/

function detectGenre(genre?: string, input?: string): 'honghuang' | 'western' | 'scifi' | 'xianxia' | 'history' | 'urban' | 'general' {
  const combined = ((genre || '') + ' ' + (input || '')).toLowerCase()
  // 西幻优先级最高（防止盘龙等被误判）
  if (WESTERN_KEYWORDS.test(combined)) return 'western'
  // 科幻其次
  if (SCIFI_KEYWORDS.test(combined)) return 'scifi'
  // 洪荒再次
  if (HONGHUANG_KEYWORDS.test(combined)) return 'honghuang'
  // 仙侠/玄幻
  if (XIANXIA_KEYWORDS.test(combined)) return 'xianxia'
  // 历史
  if (HISTORY_KEYWORDS.test(combined)) return 'history'
  return 'general'
}

function getGenreSpecificRules(stepKey: string, genreType: string): string {
  // 🔥🔥🔥 历史/架空历史题材·绝对铁律（最高优先级·违反则输出作废）
  if (genreType === 'history') {
    const historyCommon = `
【🔥🔥🔥 历史题材·绝对铁律·最高优先级·违反则输出作废】
当前为【历史/架空历史】题材（本作背景为明末清初南明永历朝），绝对禁止出现任何仙侠/玄幻/修真/系统流/西幻/科幻/超自然元素：
1. 绝对禁止仙侠/玄幻词汇：修仙、修真、修炼、灵气、灵根、金丹、元婴、筑基、渡劫、法宝、功法、宗门、仙门、御剑、腾云、仙界、凡躯、鸿蒙、诸天万界、独断万古、逆斩、登临、觉醒、血脉、天赋异禀、系统、面板、签到、金手指（本作"金手指"只能是"后世知识/历史先知/兵法谋略"等现实向能力，绝不可写成超自然系统）、穿越（仅可写"现代灵魂穿越"的背景设定，正文与设定不得出现系统提示）、宗门大比、秘境、妖兽、灵兽、丹药、符箓、阵法（修仙义）。
2. 绝对禁止系统流/网文模板化成长标签：起源觉醒、初露锋芒、危机历练、觉醒时刻、突破自我、凡躯逆天、一路高歌、废柴崛起、逆袭打脸（作为章节/阶段标签时）、装逼、装X。阶段名/卷名/章节名必须为本作真实历史剧情节点，禁止套用通用成长模板。
3. 人物姓名铁律：必须使用符合明末清初特征的中式历史姓名（姓+名，2-3字），严禁仙侠风意境名（如洛清寒、幽冥子、凌霄子、萧清风、林婉儿、柳若烟、赵明远、林清玄、云逸尘、苏沐雪等飘渺仙侠名）。本作推荐使用真实历史人物姓名或同风格原创名：朱由榔、李定国、郑成功、孙可望、李成栋、吴三桂、瞿式耜、陈邦彦、王夫之、张煌言、何腾蛟、尚可喜、孔有德、马吉翔、陈子壮、张家玉、李来亨、刘文秀、白文选等。
4. 所有设定必须严格贴合真实历史背景（明末清初南明永历朝）：真实历史地名（肇庆、广州、桂林、昆明、安龙、梧州、衡州、新会、曲靖、浔州等）、真实势力（南明永历朝廷、清廷、大西军余部、郑氏水师、地方军阀、沙定洲之乱等）、真实矛盾（抗清复明、朝廷党争、将相不和、粮饷困局、孙可望跋扈、三藩反复）。
5. 力量体系（powerSystem）铁律：历史题材绝无"修炼/境界"体系！本作力量体系应为【朝堂权力体系】——以兵力多寡、将领才能、城池得失、粮饷供应、民心向背、外交纵横为核心。worldPowerSystem.type必须填"明朝朝堂权力体系/南明朝堂权力体系/明末朝堂权力体系/朝堂权力体系"等带朝代前缀的体系名，name与type保持一致（如name="明朝朝堂权力体系"，type="明朝朝堂权力体系"），绝对禁止填"军政体系/权谋体系/冷兵器战争体系/明末军政格局/南明军事力量体系/本作无任何超自然/本作无任何体系/无任何超自然/无超自然/无体系/无系统"等占位文本。
6. 伏笔（foreshadowings）铁律：必须设计≥15条具体、可落地的历史伏笔，每条绑定真实历史线索（如孙可望的野心与篡位隐患、李成栋反复无常的隐患、永历帝被孙可望挟持于安龙的危局、郑成功与其父郑芝龙立场对立、吴三桂之反复、桂林留守瞿式耜的死局预伏、东阁党争、大陆战场与海上郑氏的呼应、李定国两厥名王之战的伏笔等），每条写明埋设章节与回收章节、关联人物，禁止空泛。
7. 人物关系（relationships）铁律：必须为真实历史人际关系——君臣、将相、盟友、敌对、翁婿、师生、同乡、叛降、亲族，绝对禁止仙侠式"师徒/同门/宗门/道侣"关系。
8. 大纲阶段名（outline stages）铁律：每卷/每阶段的stageName必须是本作真实历史剧情节点（如"肇庆监国""湘桂大捷""安龙之困""两厥名王""昆明惊变""出走缅甸"），绝对禁止"起源觉醒/初露锋芒/危机历练/觉醒时刻"等系统流成长模板标签。
`
    if (stepKey === 'outline' || stepKey === 'keyPlots' || stepKey === 'chapters') {
      return historyCommon + `
【历史题材·大纲/分卷铁律·补充】
- 输出JSON的stages[].stageName必须是本作真实历史剧情阶段名（4-8字），示例：「肇庆监国」「湘桂大捷」「安龙之困」「两厥名王」「昆明惊变」「出走缅甸」。
- 每个stage的mainEvent必须描述具体历史事件与冲突（谁、在何地、发生了什么转折），不得写"主角觉醒""实力提升"等虚词。
- 章节标题（chapters[].title）必须是具体历史剧情画面（如"肇庆风雪夜，孤臣擎起残明旗"），禁止"初露锋芒""危机历练"等模板标题，禁止仙侠风标题。
`
    }
    if (stepKey === 'characters') {
      return historyCommon + `
【历史题材·角色铁律·补充】
- 角色姓名必须历史中文风（朱由榔、李定国、郑成功…），绝对禁止仙侠意境名（洛清寒/幽冥子/凌霄子/萧清风/林婉儿等）。
- realmLevel字段：历史题材填"官职/爵位/军职"（如"锦衣卫指挥使""安西将军""东阁大学士""平南王""宜章伯"），绝对禁止填"金丹期/筑基期/元婴期"等修炼等级。
- weapons字段：历史题材填真实冷兵器/甲胄/火器（如"雁翎刀""鸟铳""红夷大炮""山文甲""神臂弓"），绝对禁止填"本命飞剑""法宝""灵器"。
- techniques字段：历史题材填真实军事/权谋技艺（如"戚家军鸳鸯阵""火器操典""八阵图""纵横之术""屯田之策"），绝对禁止填"御剑术""吐纳法""功法"。
- 角色身份必须贴合明末清初历史（宗室/文臣/武将/藩王/水师/宦官/降将/义军），绝对禁止"修士/仙人/宗门长老"。
`
    }
    if (stepKey === 'powerSystem') {
      return historyCommon + `
【历史题材·力量体系铁律·补充】
- protagonistAbility.name：只能是与"后世知识/历史先知/兵法谋略/现代思维"相关的能力名（如"后世之智""先知先觉""兵法学识""格物之能"），绝对禁止"某某系统""某某诀""灵根觉醒"。
- worldPowerSystem.type="明朝朝堂权力体系"，name与type保持一致（如"明朝朝堂权力体系"/"南明朝堂权力体系"/"明末朝堂权力体系"/"朝堂权力体系"），核心维度：兵力、将才、城池、粮饷、民心、外交。绝对禁止修炼/境界维度，禁止填"军政体系/权谋体系/冷兵器战争体系/明末军政格局/南明军事力量体系"，绝对禁止用"本作无任何超自然/本作无任何体系/无超自然/无体系/无系统"等占位文本代替真实体系名。

【🔥🔥🔥 历史题材·金手指互斥铁律·必须二选一·禁止混搭·违反则输出作废】
金手指必须二选一，禁止把知识内容和物理物件机制混搭在同一条金手指里：
- 选项A·【纯知识类】：仅由"后世知识/历史先知/兵法谋略/现代思维/格物之能"等纯知识性能力构成。name 必须是抽象的能力名（如"后世之智""先知先觉""兵法学识""格物之能""永历中兴经略"等），绝对禁止任何物理物件（玉佩/戒指/宝物/神器/法宝/古物/秘宝/古剑/古书/铜镜/印章/吊坠/玉玦/古镜/古印/古币/玉器/青铜器/瓷瓶/古籍/古画/铜钱/玉璧/玉环/玉牌/佩玉/玉坠/权杖/令牌/符印）出现在 name 或 description 或 abilities 或 limitations 或 evolution 任一字段中。如果出现能量消耗/破碎/损坏/反噬/封印等物件机制描述，整条金手指作废。
- 选项B·【纯神器类】（仅限单件实物+无超自然机制）：仅含单一具体物件（如一本真实的明代兵书《武备志》、一把真实的雁翎刀、一件真实的山文甲、一匹战马），name 必须是该物件的具体名称；禁止出现"后世知识/历史先知/兵法谋略/现代思维/记忆/预知未来/后世"等知识类内容；物件本身必须符合明末历史实物（不能是修真宝物/异能装置/系统面板）。如果出现"内含/蕴含/承载/封印/预知/记忆"等知识性内容，整条金手指作废。
description / abilities / limitations / evolution 4 个字段都必须服从同一类型，绝对禁止玉佩+知识、戒指+系统、宝物+后世记忆 等混搭。type 字段为"知识记忆"时只允许选项A；type 为其它类型时只允许选项B。
`
    }
    if (stepKey === 'relationships') {
      return historyCommon + `
【历史题材·人物关系铁律·补充】
- relationshipType必须是：君臣、将相、盟友、敌对、翁婿、师生、同乡、叛降、亲族 之一，绝对禁止：师徒、同门、道侣、宗门。
`
    }
    if (stepKey === 'factions') {
      return historyCommon + `
【历史题材·势力铁律·补充】
- 势力类型必须是：朝廷、藩王、军阀、水师、文官集团、地方武装、外敌（清廷）、降清势力 之一。绝对禁止：宗门、仙门、门派、教派（修仙义）、学院、公会、公司。
`
    }
    if (stepKey === 'worldbuilding') {
      return historyCommon + `
【历史题材·世界观铁律·补充】
- technologyLevel必须填写明末真实科技水平（冷兵器为主、火器初兴、耕织为本、海运贸易），绝对禁止"青铜/铁器/修炼文明"等词。
- 地理环境必须使用真实明末地名与山河（岭南、长江流域、云贵高原、湘江、漓江、五岭、琼州海峡），绝对禁止"灵脉/洞天/秘境/灵气"。

【🔥🔥🔥 历史题材·力量体系·境界划分铁律·补充·必须配对格式】
【境界划分】块严禁写成"书吏-皂隶-巡拦 → 战兵-马卒-力士 → ...""这种单行箭头平铺格式！必须严格使用品阶成对的文武对照格式，每行格式如下：
  品阶 → 文『职事·散阶』 ｜ 武『武职·爵位』
示例（未入流-正四品 共 13 品，每品一行）：
  未入流→文『书吏·皂隶·巡拦』｜武『战兵·马卒·力士』
  从九品→文『县主簿·府经历·司狱·巡检』｜武『百户·镇抚·典仗』
  正九品→文『府知事·县典史·驿丞·闸官』｜武『百户·所镇抚』
  ...（中间省略 10 行，依次为从八品-正四品）
  正四品→文『按察使（重镇）·布政使司参政』｜武『提督镇守总兵-九边副总兵』
绝对禁止：单行 → 箭头平铺、顿号列表、纯品阶名列表、修真境界术语（炼气/筑基/金丹）、作废占位（无超自然/无体系/无系统）。
`
    }
    if (stepKey === 'synopsis' || stepKey === 'idea') {
      return historyCommon + `
【历史题材·简介/创意铁律·补充】
- 一句话简介（tagline）必须为本作真实历史悬念与爽点（如"大明最后的皇帝，在群奸环伺中南奔数千里，终借名将李定国之刀两厥名王、一度中兴"），绝对禁止"逆斩仙魔/登临鸿蒙/凡躯逆天"等仙侠词。
- 金手指只能写成"后世灵魂带来的历史先知与兵谋"，绝不可写超自然系统。
`
    }
    return historyCommon
  }

  if (genreType !== 'honghuang') {
    // 非洪荒题材：添加明确的禁止规则，防止LLM使用洪荒设定
    return `
【🔥🔥🔥 题材隔离铁律·最高优先级·违反则输出作废】
当前题材并非洪荒/封神/巫族/上古神话，绝对禁止出现任何洪荒专属词汇和设定：
1. 绝对禁止出现：巫族、祖巫、帝江、共工、祝融、烛龙、玄冥、后土、句芒、蓐收、强良、奢比尸、天吴、翕兹、帝俊、太一、鲲鹏、女娲、三清、元始天尊、通天教主、老子、接引、准提、阐教、截教、人教、西方教、妖庭、巫妖量劫、龙汉初劫、封神之战、混元大罗金仙、斩三尸、先天灵宝、洪荒大陆、不周山、三十三天、幽冥地府、四海八荒
2. 绝对禁止使用洪荒力量体系："混元大罗金仙→准圣→大罗金仙→太乙金仙→金仙→玄仙→真仙→天仙→地仙→人仙"
3. 绝对禁止洪荒势力分类：巫族/妖族/仙道/人族的分类方式
4. 所有设定必须严格贴合当前题材，使用当前题材对应的词汇和体系框架
`
  }
  
  // 洪荒题材：注入洪荒专属规则（仅在明确匹配洪荒题材时）
  if (stepKey === 'idea') {
    return `
【🔥 洪荒题材·金手指系统名铁律】
当前为洪荒/封神/巫道题材：
- systemName必须围绕洪荒/巫道主题设计，如"祖巫传承""血祭苍穹""图腾之魂""混沌珠""先天灵宝""巫祖血脉""天命巫种"等
- 未选择系统/签到/面板等流派标签时，绝对禁止systemName包含"系统""面板""签到""商城""任务"等现代词汇
- 主题含"图腾""巫道""祖巫"等词时，金手指名称必须体现巫道/图腾特征
`
  }
  
  if (stepKey === 'worldbuilding') {
    return `
【🔥🔥🔥 洪荒封神流世界观框架·最高优先级】
当前为洪荒/封神/巫道题材，必须严格遵循洪荒世界观框架：
1. 时代背景：必须是洪荒/上古/远古时期，明确写出纪元（龙汉初劫/巫妖大战/三皇五帝/封神之战/西游量劫），写明量劫阶段、圣人状态、主要势力格局
2. 地理环境：必须包含洪荒大陆/不周山/三十三天/幽冥地府/四海八荒等洪荒典型地理框架
3. 势力格局：必须体现"圣人/准圣/大罗金仙"顶级层级，以及"阐教/截教/人教/西方教"或"妖族/巫族/人族"势力对立
4. 力量体系：必须使用"混元大罗金仙（圣人）→准圣（三尸/功德/斩道）→大罗金仙→太乙金仙→金仙→玄仙→真仙→天仙→地仙→人仙"洪荒标准体系
5. 世界规则：必须体现"天道/鸿钧/量劫/气运/功德/斩三尸/灵宝/阵法/丹道"等洪荒核心概念
6. 历史背景：必须包含"开天辟地/龙凤初劫/巫妖大战/女娲造人/三皇五帝/封神之战"等洪荒大事件
7. technologyLevel必须填写上古修炼文明水平，绝对禁止出现青铜冶炼、铁器、牛耕、弩车、马车等历史元素

【🔥🔥🔥 洪荒题材·势力分类严格区分铁律】
所有势力必须严格按巫/妖/仙/人四类设定：
- 巫族势力：名称含"巫"字，首领称祖巫/大巫/巫祝，代表势力：祖巫殿、巫族祭坛、九黎部落
- 妖族势力：名称含"妖"字，首领称妖帝/妖皇/妖王，代表势力：妖族天庭、万妖窟、妖皇宫
- 仙道势力：名称含"教/门/宗/仙"，首领称圣人/教主/掌门，代表势力：阐教、截教、人教、西方教
- 人族势力：名称含"族/部落/国/朝"，首领称人皇/族长/帝王，代表势力：华夏部落、炎黄部落
⚠️ 具体人物身份绝对固定：帝江(速度祖巫)、共工(水之祖巫)、祝融(火之祖巫)、烛龙(时间祖巫)、玄冥(雨之祖巫)、后土(土之祖巫)、帝俊(妖帝)、太一(妖皇)、鲲鹏(妖族大圣)、女娲(人族圣母/妖族圣人)、三清(圣人)、接引准提(西方教教主)，绝对禁止身份混淆！
`
  }
  
  if (stepKey === 'powerSystem') {
    return `
【🔥🔥🔥 洪荒题材·力量体系铁律·最高优先级】
当前为洪荒/巫道/封神题材：
- protagonistAbility.name必须与前文idea确定的金手指名完全一致，禁止修改
- worldPowerSystem.type必须是：洪荒体系、巫族体系、仙道体系、神道体系、妖修体系、巫道体系 之一（优先洪荒/巫族/巫道体系）
- worldPowerSystem.name必须包含"洪荒"或"巫"或"仙"关键词，如"洪荒万道体系""巫族肉身体系""巫道双修体系"
- 未选择流派标签时，金手指绝对不能是系统类，名称不能含"系统""面板""签到"等现代词
- 推荐金手指名称：祖巫传承、血祭苍穹、图腾之魂、混沌珠、先天灵宝、巫祖血脉、天命巫种、盘古传承、巫道本源
`
  }
  
  if (stepKey === 'characters') {
    return `
【🔥🔥🔥 洪荒题材·角色身份正确性铁律·最高优先级】
当前为洪荒/封神/上古/神话题材，角色身份必须符合洪荒设定：
1. 十二祖巫身份绝对正确：帝江(速度祖巫之首)、共工(水之祖巫)、祝融(火之祖巫)、烛龙(时间祖巫)、玄冥(雨之祖巫)、后土(土之祖巫，后化轮回)、句芒(木)、蓐收(金)、强良(雷)、奢比尸(天气)、天吴(风)、翕兹(电)，绝对禁止身份混淆
2. 著名神话人物身份绝对正确：女娲(人族圣母/妖族圣人)、伏羲(人族始祖)、神农(三皇)、黄帝(五帝之首)、蚩尤(九黎之主)、帝俊(妖族妖帝)、太一(妖族妖皇)、三清(圣人)、接引准提(西方教教主/圣人)、鲲鹏(妖族大圣)
3. 绝对禁止串小说角色：严禁使用药老、萧战、海波东、萧炎、林动、韩立、叶凡等其他小说角色名
4. 祖巫必须巫族身份，妖族必须妖族身份，人族必须人族身份，圣人必须圣人级别
`
  }
  
  if (stepKey === 'factions') {
    return `
【🔥🔥🔥 洪荒题材·势力分类严格区分铁律·最高优先级】
当前为洪荒/封神/巫道题材，所有势力必须严格按巫/妖/仙/人四类设定：
- 巫族势力：名称含"巫"字，首领称祖巫/大巫/巫祝，代表势力：祖巫殿、巫族祭坛、九黎部落
- 妖族势力：名称含"妖"字，首领称妖帝/妖皇/妖王，代表势力：妖族天庭、万妖窟、妖皇宫
- 仙道势力：名称含"教/门/宗/仙"，首领称圣人/教主/掌门，代表势力：阐教、截教、人教、西方教
- 人族势力：名称含"族/部落/国/朝"，首领称人皇/族长/帝王，代表势力：华夏部落、炎黄部落
⚠️ 具体人物身份绝对固定：帝江(速度祖巫)、共工(水之祖巫)、祝融(火之祖巫)、烛龙(时间祖巫)、玄冥(雨之祖巫)、后土(土之祖巫)、帝俊(妖帝)、太一(妖皇)、鲲鹏(妖族大圣)、女娲(人族圣母/妖族圣人)、三清(圣人)、接引准提(西方教教主)，绝对禁止身份混淆！
⚠️ 势力类型必须是：教派、妖族、巫族、人族部落、龙宫、地府、天庭、圣地道场等，绝对禁止出现宗门、学院、商会、公司、帝国、王国、朝廷、官府等洪荒不存在的势力类型！
`
  }
  
  if (stepKey === 'synopsis') {
    return `
【🔥🔥🔥 洪荒题材·简介卖点铁律】
当前为洪荒/封神/巫道题材，简介卖点必须严格贴合洪荒世界观：
- 必须使用洪荒专属名词：巫族、祖巫、妖族、量劫、圣人、天道、气运、灵宝等
- 金手指描述必须符合洪荒题材（祖巫传承/先天灵宝/巫道血脉等，绝对禁止系统/面板/签到等现代词汇除非用户明确选择系统流）
- 核心冲突必须围绕洪荒量劫/巫妖大战/封神之战/圣人博弈展开
- 绝对禁止出现其他题材词汇（修仙宗门/魔法斗气/机甲科技等）
`
  }
  
  if (stepKey === 'relationships') {
    return `
【🔥🔥🔥 洪荒题材·人物关系铁律】
当前为洪荒/封神/巫道题材，人物关系必须符合洪荒设定：
- 巫族之间：祖巫与大巫/巫祭是传承/部落关系，十二祖巫是兄弟姐妹关系
- 妖族之间：妖帝/妖皇与妖帅/大妖是君臣关系，帝俊太一为兄弟
- 巫妖之间：必须是敌对/仇恨关系（巫妖量劫）
- 仙道之间：三清是师兄弟关系，与西方教是竞争/合作关系
- 绝对禁止跨题材的关系设定（如宗门师徒/魔法契约等）
`
  }
  
  if (stepKey === 'outline' || stepKey === 'keyPlots' || stepKey === 'chapters') {
    return `
【🔥🔥🔥 洪荒题材·剧情铁律】
当前为洪荒/封神/巫道题材，剧情必须严格贴合洪荒世界观：
- 核心冲突围绕量劫（龙汉初劫/巫妖量劫/封神量劫）展开
- 境界突破使用洪荒体系：地仙→天仙→真仙→玄仙→金仙→太乙金仙→大罗金仙→准圣→圣人
- 绝对禁止出现其他题材的修炼/升级/战斗描写
- 重要剧情节点必须符合洪荒时间线（开天→龙凤初劫→巫妖大战→女娲造人→三皇五帝→封神之战）
`
  }
  
  return ''
}

export const PROMPT_LIBRARY: Record<string, StepPrompt> = {
  idea: IDEA_PROMPT,
  worldbuilding: WORLDBUILDING_PROMPT,
  powerSystem: POWER_SYSTEM_PROMPT,
  characters: CHARACTERS_PROMPT,
  factions: FACTIONS_PROMPT,
  relationships: RELATIONSHIPS_PROMPT,
  outline: OUTLINE_PROMPT,
  keyPlots: KEY_PLOTS_PROMPT,
  chapters: CHAPTERS_PROMPT,
  synopsis: SYNOPSIS_PROMPT,
  imitate: IMITATE_PROMPT,
  content: CONTENT_PROMPT,
}

/**
 * 构建完整的系统提示词
 * 将模板中的 {{变量}} 替换为实际值
 */
export function buildSystemPrompt(
  stepKey: string,
  params: {
    input?: string
    genre?: string
    previousContext?: string
    imitateContext?: string
    chapterContext?: string
    volumeContext?: string
    bookTitle?: string
    bookGenre?: string
    bookData?: string
    namingConstraint?: string
    imitate?: Record<string, unknown>
    extra?: Record<string, unknown>
  }
): { systemPrompt: string; schema: string; temperature: number; maxTokens: number } {
  const prompt = PROMPT_LIBRARY[stepKey]
  if (!prompt) {
    throw new Error(`Unknown step key: ${stepKey}`)
  }

  // 生成仿写约束
  function genImitateConstraint(imitate: Record<string, unknown> | undefined, step: string): string {
    if (!imitate) return ''
    const origChars = ((imitate.characters as Array<Record<string, unknown>>) || []).map(function(c: Record<string, unknown>) { return c.name }).join('、')
    const origTitle = (imitate.title as string) || '原著作品'
    const origGenre = (imitate.genre as string) || ''
    const origKeywords = ((imitate.keywords as unknown[]) || (imitate.tags as unknown[]) || []).join('、')
    const origAuthor = (imitate.author as string) || ''
    const isFanfic = imitate.isFanfiction === true

    if (isFanfic) {
      return '\n【同人创作模式·最高优先级】\n当前为《' + origTitle + '》同人创作，必须使用原著角色名（' + (origChars || '原著全部角色') + '），沿用原著世界观地名势力名，当前环节：' + step + '\n'
    } else {
      // 仿写模式：100%原创，禁止原著专有名词
      let forbiddenNames = origChars || '林雷、巴鲁克、迪莉娅、贝贝、德林柯沃特、霍格'
      // 针对知名作品内置专有名词黑名单
      const titleLower = (origTitle || '').toLowerCase()
      if (origTitle && (origTitle.indexOf('盘龙') !== -1 || titleLower.indexOf('panlong') !== -1 || titleLower.indexOf('coiling dragon') !== -1)) {
        forbiddenNames = '林雷、巴鲁克、迪莉娅、贝贝、沃顿、耶鲁、雷诺、乔治、霍格、林蒙、德林柯沃特、奥利维亚、德斯黎、贝鲁特、丹宁顿、奥布莱恩、帝林、武神、大祭司、希塞、普斯罗、雷斯晶、帕瑟芬妮'
      }
      return '\n【仿写模式·严禁抄袭·最高优先级】\n你正在仿写《' + origTitle + '》的结构、节奏、爽点设计，但所有内容必须100%原创！\n当前环节：' + step + '\n🚨 绝对禁止（违反即输出作废）：\n1. 严禁使用原著角色名（' + forbiddenNames + '等任何原著出现过的人名）\n2. 严禁使用原著地名/势力名/功法名/道具名\n3. 严禁复制原著剧情对话或经典场景\n4. 严禁使用真实历史地名/朝代名（如拜占庭、罗马、大秦、大唐等）\n5. 角色姓名姓氏必须与家族背景一致，必须原创\n✅ 允许借鉴：结构框架、节奏设计、爽点排布、成长曲线\n✅ 必须原创：全新角色名、全新地名、全新势力、全新剧情\n所有名称、地点、势力、道具必须100%原创，与原著无任何重合！\n'
    }
  }

  let systemPrompt = prompt.systemPrompt
  systemPrompt = systemPrompt.replace(/\{\{input\}\}/g, params.input || '')
  systemPrompt = systemPrompt.replace(/\{\{genre\}\}/g, params.genre || '用户选择的题材')
  // 🔥🔥🔥 P0 修复（2026-08-23）：限制注入的前文上下文字数上限，防止 DeepSeek 等模型生成的
  //   冗长结构化数据（实测 characters 60KB）被整体注入导致下游提示词过大 → 模型超时/挂起（如 relationships）。
  //   仅截断"前文设定"，保留开头关键设定（主角/世界观/力量体系在前，角色/势力在后），兼顾质量与可用性。
  const _prevCtx = (params.previousContext || '（暂无前文设定）')
  const _ctxCap = 6000
  // 🔥🔥🔥 2026-11-01 修复（P0-2·漂移主因）：原实现 `_prevCtx.slice(0, 6000)` 是**按字符硬切**，
  //   带来三个确定性缺陷（实测均复现）：
  //     ① 切点落在人名/JSON 中间 → 模型看到半个名字，会"补"一个像但不同的名字（角色漂移）；
  //     ② 拼装顺序是【关键词 → 题材禁令 → 拆书参考(无上限) → idea → 世界观 → 金手指 → 人物 → 势力 → 大纲 → 简介】，
  //        仿写模式下"拆书参考"常单独超 6000 字，导致**本作全部设定被整段截掉**；
  //     ③ 截断后没有任何提示说明"哪些没了"，模型只能自由发挥（跑题/OOC）。
  //   现改为「按段落裁剪 + 优先级」：
  //     · 参考素材段（拆书/原著/对标）优先级最低，超限时首先丢弃；
  //     · 本作设定段（主角/世界观/金手指/人物/势力/大纲/简介）优先保留；
  //     · 单段自身超限时，按句末标点回退到完整句子，绝不留半个名字；
  //     · 文本过长时在唯一入口处统一裁剪（此处），下游不再二次硬切。
  const _isRefSegment = function (p: string): boolean {
    return /【参考|拆书|原著|参考素材|Reference Work|对标作品|参考作品/.test(p)
  }
  const _safeCut = function (s: string, cap: number): string {
    if (s.length <= cap) return s
    var _win = s.slice(0, cap)
    // 回退到最近的句末标点/换行，避免切断人名或 JSON 键值
    var _last = Math.max(
      _win.lastIndexOf('。'), _win.lastIndexOf('；'), _win.lastIndexOf('！'),
      _win.lastIndexOf('？'), _win.lastIndexOf('\n'), _win.lastIndexOf('，')
    )
    return _last > cap * 0.6 ? _win.slice(0, _last + 1) : _win
  }
  const _capContext = function (raw: string, cap: number): string {
    if (raw.length <= cap) return raw
    var _parts = raw.split('\n')
    var _keep: string[] = []
    var _ref: string[] = []
    for (var _pi = 0; _pi < _parts.length; _pi++) {
      var _p = _parts[_pi]
      if (!_p) continue
      if (_isRefSegment(_p)) _ref.push(_p); else _keep.push(_p)
    }
    var _out = ''
    for (var _ki = 0; _ki < _keep.length; _ki++) {
      var _seg = _keep[_ki]
      if ((_out.length + _seg.length + 1) > cap) {
        // 本段放不下：若当前为空（单段超限），按句末回退截取；否则丢弃本段及之后
        if (!_out) { _out = _safeCut(_seg, cap); break }
        break
      }
      _out += (_out ? '\n' : '') + _seg
    }
    var _room = cap - _out.length
    if (_room > 80 && _ref.length) {
      _out += '\n' + _safeCut(_ref.join('\n'), _room - 1)
    }
    return _out + '\n…[前文过长，已按段落优先级裁剪（保留本作设定，优先舍弃参考素材）]'
  }
  systemPrompt = systemPrompt.replace(/\{\{previousContext\}\}/g, _capContext(_prevCtx, _ctxCap))
  systemPrompt = systemPrompt.replace(/\{\{imitateContext\}\}/g, params.imitateContext || '')
  systemPrompt = systemPrompt.replace(/\{\{chapterContext\}\}/g, params.chapterContext || '')
  systemPrompt = systemPrompt.replace(/\{\{volumeContext\}\}/g, params.volumeContext || '')
  systemPrompt = systemPrompt.replace(/\{\{bookTitle\}\}/g, params.bookTitle || '')
  systemPrompt = systemPrompt.replace(/\{\{bookGenre\}\}/g, params.bookGenre || '')
  systemPrompt = systemPrompt.replace(/\{\{bookData\}\}/g, params.bookData || '')
  systemPrompt = systemPrompt.replace(/\{\{namingConstraint\}\}/g, params.namingConstraint || '')
  systemPrompt = systemPrompt.replace(/\{\{imitateConstraint\}\}/g, genImitateConstraint(params.imitate, stepKey))
  systemPrompt = systemPrompt.replace(/\{\{schema\}\}/g, prompt.schema)
  
  // 🔥 动态注入题材专属规则（核心修复：仅当题材匹配时才注入洪荒等专属规则，否则注入题材隔离禁令）
  const detectedGenre = detectGenre(params.genre, params.input)
  const genreRules = getGenreSpecificRules(stepKey, detectedGenre)
  systemPrompt = systemPrompt.replace(/\{\{genreSpecificRules\}\}/g, genreRules)
  // 如果prompt中没有占位符，则追加到末尾
  if (genreRules && systemPrompt.indexOf('题材隔离铁律') === -1 && systemPrompt.indexOf('洪荒题材') === -1) {
    systemPrompt = genreRules + '\n' + systemPrompt
  }

  // 自动追加仿写约束（双重保险）
  const ic = genImitateConstraint(params.imitate, stepKey)
  if (ic && systemPrompt.indexOf('仿写模式·严禁抄袭') === -1 && systemPrompt.indexOf('同人创作模式') === -1) {
    systemPrompt += '\n' + ic
  }

  // 🔥 2026-08-21 全局追加：禁止字段值前面加 [字段名]/【字段名】 等模板标签前缀
  // （修复 GLM-4-9B 等小模型把"字段说明"当作"输出格式"重复打印的问题，如 coreGoldenQuote: "[核心金句]"）
  const NO_PLACEHOLDER_PREFIX_RULE = `

【🔥🔥🔥 字段值纯净铁律·绝对不可违反】
所有字段的值必须【直接是内容本身】，绝对禁止在字段值前面添加任何形式的标签前缀，包括但不限于：
- 禁止：[xxx]、【xxx】、「xxx」、『xxx』、#xxx#、*xxx* 等任何方括号/书名号/星号包裹的标签
- 禁止："主题思想：xxx""文风定位：xxx""核心金句：xxx" 等"标签+冒号+内容"的格式
- 禁止：把字段名重复一遍再写内容（如 coreGoldenQuote 字段值不要写成"核心金句：xxx"，而应直接是"xxx"）
- 🔥 禁止：给 JSON 键名加前后下划线包裹（如 _coreGoldenQuote_）。键名必须严格使用 Schema 中给出的英文名（coreGoldenQuote、commercialPositioning 等），不加任何修饰。
- 禁止：在值中加斜体下划线包裹（如 _废柴逆袭流_），如需强调可写"废柴逆袭流"本身

正确示例：coreGoldenQuote 字段的合法值为 "一念成佛，一念成魔"
错误示例：coreGoldenQuote 字段的错误值为 "[核心金句]一念成佛，一念成魔" 或 "_coreGoldenQuote_":"核心金句：一念成佛"

此铁律适用于所有字段（字符串/数组元素/对象子字段），违反此铁律的输出视为无效。`
  if (systemPrompt.indexOf('字段值纯净铁律') === -1) {
    systemPrompt += NO_PLACEHOLDER_PREFIX_RULE
  }

  return {
    systemPrompt,
    schema: prompt.schema,
    temperature: prompt.temperature,
    maxTokens: prompt.maxTokens,
  }
}